import sys
from collections import defaultdict

class Node:
    def __init__(self, weight):
        self.weight = weight
        self.children = []

def dfs(node, x, memo):
    if (node, x) in memo:
        return memo[(node, x)]
    max_length = 0
    for child in node.children:
        if child.weight <= node.weight and x >= child.weight:
            max_length = max(max_length, 1 + dfs(child, x - child.weight, memo))
    memo[(node, x)] = max_length
    return max_length

def main():
    import sys
    input = sys.stdin.read().splitlines()
    q = int(input[0])
    nodes = [Node(0)]
    last = 0
    results = []
    for i in range(1, q + 1):
        query = input[i].split()
        t = query[0]
        p = int(query[1]) ^ last
        q = int(query[2]) ^ last
        if t == '1':
            new_node = Node(q)
            nodes[p].children.append(new_node)
            nodes.append(new_node)
        elif t == '2':
            memo = {}
            result = dfs(nodes[p], q, memo)
            results.append(result)
            last = result
    for result in results:
        print(result)

main()
